<?php require 'config/database.php';require 'helpers/functions.php';login_required();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();admin_required();$n=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');if($n===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)))msg('Nama atau email tidak valid.','error');else{$s=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');$s->execute([$n,$phone?:null,$email?:null,$address?:null]);msg('Pemasok ditambahkan.');}go('suppliers.php');}$rows=$pdo->query('SELECT s.*,COUNT(p.id) total FROM suppliers s LEFT JOIN products p ON p.supplier_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();header_html('Pemasok');if($_SESSION['user']['role']==='admin')echo '<section><form method="post"><input type="hidden" name="csrf" value="'.e(token()).'"><label>Nama</label><input name="name" required><label>Telepon</label><input name="phone"><label>Email</label><input type="email" name="email"><label>Alamat</label><input name="address"><button>Tambah Pemasok</button></form></section>';echo '<section><table><tr><th>Nama</th><th>Telepon</th><th>Email</th><th>Alamat</th><th>Produk</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['email']).'</td><td>'.e($r['address']).'</td><td>'.e($r['total']).'</td></tr>';echo '</table></section>';footer_html();